--Find employees whose average order value is greater than ₹10,000

SELECT
    e.employeeid,
    e.employeename,
    AVG(o.quantity * p.price) AS average_order_value
FROM employee__ e
JOIN order__ o
    ON e.employeeid = o.employeeid
JOIN product__ p
    ON o.productid = p.productid
GROUP BY e.employeeid, e.employeename
HAVING AVG(o.quantity * p.price) > 10000;

--Find the cumulative revenue generated by each customer over time

WITH OrderRevenue AS (
    SELECT
        o.customerid,
        o.orderid,
        o.orderdate,
        o.quantity * p.price AS revenue
    FROM order__ o
    JOIN product__ p
        ON o.productid = p.productid
)
SELECT
    customerid,
    orderid,
    orderdate,
    revenue,
    SUM(revenue) OVER (
        PARTITION BY customerid
        ORDER BY orderdate, orderid
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS cumulative_revenue
FROM OrderRevenue;